ALTER TABLE "batches" ADD COLUMN "is_flash_sale" boolean DEFAULT false NOT NULL;--> statement-breakpoint
ALTER TABLE "batches" ADD COLUMN "flash_sale_discount_percent" integer;--> statement-breakpoint
